/* @autogenerated */
import { signal } from '@angular/core';

// Igualdad por defecto: identidad para primitivos y comparación superficial de claves para objetos,
// de modo que un mapper que devuelve objetos nuevos ({ id }) siga encontrando el elemento.
function shallowEquals(one: unknown, other: unknown): boolean {
  if (Object.is(one, other)) {
    return true;
  }
  if (typeof one !== 'object' || typeof other !== 'object' || one === null || other === null) {
    return false;
  }
  const oneKeys = Object.keys(one);
  const otherKeys = Object.keys(other);
  return (
    oneKeys.length === otherKeys.length &&
    oneKeys.every((key) => Object.is((one as Record<string, unknown>)[key], (other as Record<string, unknown>)[key]))
  );
}

export class SelectionModel<T> {
  private selectedItems = signal<T[]>([]);

  private mapper?: (item: any) => T;

  private equals: (one: T, other: T) => boolean = shallowEquals;

  get selected() {
    return this.selectedItems.asReadonly();
  }

  modelMapper(mapper: (item: any) => T) {
    this.mapper = mapper;
  }

  modelEquals(equals: (one: T, other: T) => boolean) {
    this.equals = equals;
  }

  select(items: any[]) {
    this.selectedItems.set(items.map((row) => this.map(row)));
  }

  toggle(item: any) {
    const value = this.map(item);
    this.selectedItems.update((items) =>
      items.some((current) => this.equals(current, value))
        ? items.filter((current) => !this.equals(current, value))
        : [...items, value],
    );
  }

  /** @deprecated Usar {@link toggle}. */
  toogle(item: any) {
    this.toggle(item);
  }

  isSelected(item: any) {
    const value = this.map(item);
    return this.selectedItems().some((current) => this.equals(current, value));
  }

  clearSelection() {
    this.selectedItems.set([]);
  }

  private map(item: any): T {
    return this.mapper ? this.mapper(item) : item;
  }
}
